code.java:
class Solution {
    public int[] runningSum(int[] nums){
        for(int i=1;i<nums.length;i++)nums[i]+=nums[i-1];
        return nums;
    }
}

code.kotlin:
class Solution {
    fun runningSum(nums:IntArray):IntArray{
        for(i in 1 until nums.size)nums[i]+=nums[i-1];
        return nums
    }
}

code.cpp:
class Solution {
    public: vector<int> runningSum(vector<int>& nums){
        for(int i=1;i<(int)nums.size();++i)nums[i]+=nums[i-1];
        return nums;
    }
};
